package com.velorise.emc;
import com.velorise.emc.common.WirelessCoreTier;import net.minecraft.core.BlockPos;import net.minecraft.core.HolderLookup;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
public final class DeepboundEnderChestBlockEntity extends BlockEntity{private WirelessCoreTier tier=WirelessCoreTier.I;public DeepboundEnderChestBlockEntity(BlockPos p,BlockState s){super(VeloriseEMC.DEEPBOUND_ENDER_CHEST_BE.get(),p,s);}public WirelessCoreTier getCoreTier(){return tier;}public void setCoreTier(WirelessCoreTier t){tier=t==null?WirelessCoreTier.I:t;setChanged();}@Override protected void loadAdditional(CompoundTag t,HolderLookup.Provider r){super.loadAdditional(t,r);tier=WirelessCoreTier.byLevel(t.contains("CoreTier")?t.getInt("CoreTier"):1);}@Override protected void saveAdditional(CompoundTag t,HolderLookup.Provider r){super.saveAdditional(t,r);t.putInt("CoreTier",tier.level());}}
